\begin{lemma}[Pohozaev inequality]
\label{lem-sub-002}
Let $u$ be a $C^2$-continuous subharmonic function on the unit disk.
Then the following integral along the boundary of a smaller disk $D_R$ for some $0< R <1$
can estimated as 
\begin{equation}
\label{sub-007}
\left| \int_{S^1} \left( |u_t|^2 - |\xi_0 u|^2 \right)  \right| \leq 2 L_A(u) \cdot \left( \int_{S^1} u_t \right), 
\end{equation}
where $A = -\log R$. 
\end{lemma}

\begin{corollary}
 Let $\{\eta\}$ and $\{\theta\}$ be big cohomology classes. Let $\phi\in\PSH(X,\theta)$. Then the following are equivalent.
\hfill
\begin{enumerate}
\item $\PSH(X,\eta)\cap\mathcal{E}(X,\theta,\phi)\neq \varnothing$.

\item There exists $u\in\PSH(X,\eta)$, $v\in\mathcal{E}(X,\theta,\phi)$, $c>0$, and $h\in\mathcal{E}(X,\omega)$ such that \[u\geq v+ ch. \]

\item $\mathcal{E}(X,\eta)\cap\PSH(X,\theta,\phi)\subset \mathcal{E}(X,\theta,\phi)$.
\end{enumerate}

\end{corollary}

\begin{proposition}\label{flat_family}
	Let $<$ be a monomial ordering on $\mathcal{O}_{\mathbb{C}^n, 0}$. Assume that $z^{\alpha^1}, \dots, z^{\alpha^k}$ are monomials in $\mathcal{O}_{\mathbb{C}^n, 0}$. Then there exists $a = (a_1, \dots, a_n) \in \mathbb{N}^n$ such that
	$$
	\inf\left\{ \sum_{i=1}^n a_i \beta_i : \beta \in \mathbb{N}^n,\ z^{\beta} > z^{\alpha^j} \right\}
	> \sum_{i=1}^n a_i \alpha_i^j,\quad \text{for all } 1 \leq j \leq k.
	$$
\end{proposition}

\begin{thm}\label{thm-q-Dirichlet-unbounded}
Let $r$, $q$, $D$ be as in Theorem~\ref{thm-q-Dirichlet}, except that $D$ is unbounded. Let $f \in \ccal(\partial D)$ with $0 \leq f \leq \sup_{\partial D} f \leq M$ for some upper bound $M < +\infty$. Then there exists an almost \qbrem\ \fct\ $\Phi=\Phi_M$ on $\cld$ such that

\begin{enumerate}

\item $\Phi=f$ on $\partial D$, and $0 \leq \Phi \leq M$ on $\cld$.

\item $\Phi$ is $q$-maximal with respect to \qpsh\ \fcts\ $\psi$ with $\psi \leq f$ on $\partial D$ and $\psi \leq M$ on $\cld$. Therefore, $\pcal_{f,q,D,M} \leq \Phi$.

\item $\Phi$ is \cont\ on $\partial D$.

\item If $D$ is of bounded type, $\Phi$ is \cont\ and \qbrem\ on $\cld$. Thus, $\Phi=\pcal_{f,q,D,M_0}$ for $M_0:=\sup_{\partial D} f$.

\item If $D$ is of bounded type, $\Phi$ is the unique \qbrem\ \fct\ on $\cld$ with $\Phi=f$ on $\partial D$.% and $0\leq \Phi \leq \sup_{\partial D} f$ on $\cld$.

\end{enumerate}

\end{thm}

